(()=>{const by=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'$'+Number(n).toFixed(4);let history=[];const base='https://raw.githubusercontent.com/manishklach/InferenceFlow/main/docs/cpu-rates/';
async function load(){let fallback=false;try{const r=await fetch(base+'observations.jsonl?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error();history=(await r.text()).trim().split('\n').filter(Boolean).map(JSON.parse)}catch{fallback=true;try{const r=await fetch('cpu-observations.jsonl');if(!r.ok)throw Error();history=(await r.text()).trim().split('\n').filter(Boolean).map(JSON.parse)}catch{by('cpu-status').textContent='CPU history unavailable. Try refreshing later.';return}}const last=history.reduce((a,r)=>a>r.observed_at_utc?a:r.observed_at_utc,'');by('cpu-status').textContent=`${fallback?'Published snapshot | ':''}${Date.now()-Date.parse(last)>90*60000?'STALE | ':''}CPU quotes observed ${new Date(last).toLocaleString()}. Stock queried for 2 vCPUs only.`;by('cpu-model').innerHTML=[...new Map(history.map(r=>[r.cpu_id,r])).values()].map(r=>`<option value="${escape(r.cpu_id)}">${escape(r.group+' '+r.cpu_name+' ('+r.cpu_id+')')}</option>`).join('');if(!fallback)for(const [id,file] of [['cpu-raw','observations.jsonl'],['cpu-hourly','hourly.csv'],['cpu-daily-download','daily.csv']])by(id).href=base+file;render()}
function render(){if(!history.length)return;const latest=[...new Map(history.map(r=>[r.cpu_id,r])).values()],n=Number(by('cpu-size').value);by('cpu-table').innerHTML=latest.map(r=>`<tr><td>${escape(r.group+' '+r.cpu_name)}</td><td>${escape(r.cpu_id)}</td><td>${money(r.usd_per_vcpu_hour)}</td><td>${n} vCPU / ${n*r.ram_gb_per_vcpu} GB</td><td>${money(n*r.usd_per_vcpu_hour)}</td><td>${money(n*r.usd_per_vcpu_hour*24)}</td><td>${escape(r.availability)} at ${r.availability_vcpu_count} vCPU</td></tr>`).join('');const data=history.filter(r=>r.cpu_id===by('cpu-model').value),times=data.map(r=>Date.parse(r.observed_at_utc)),start=Math.min(...times),end=Math.max(...times);drawRateHistory(by('cpu-chart'),data,'usd_per_vcpu_hour','USD / vCPU-hour',4);by('cpu-chart-note').textContent=`USD per vCPU-hour | ${new Date(start).toISOString()} to ${new Date(end).toISOString()}. ${data.length===1?'One observation; no trend established.':'Lines connect observations; missing hours remain unknown.'}`;const groups=new Map;for(const r of data){const day=r.observed_at_utc.slice(0,10);groups.set(day,[...(groups.get(day)||[]),r.usd_per_vcpu_hour])}by('cpu-daily').innerHTML=[...groups].sort().map(([day,p])=>`<tr><td>${day}</td><td>${p.length}</td><td>${money(Math.min(...p))}</td><td>${money(p.reduce((a,b)=>a+b,0)/p.length)}</td><td>${money(Math.max(...p))}</td></tr>`).join('')}
by('cpu-size').addEventListener('change',render);by('cpu-model').addEventListener('change',render);load()})();
